# region: fold
def fold(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: render
def render(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: shape
def shape(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(gather(render(fold(raw))))

